jobs<-fread(file.path(OUT,'02_CellChat_highlow/job_manifest.csv'))[runnable==TRUE];st<-fread(file.path(OUT,'01_LLPS_stratification/cell_assignments.csv.gz'));identity<-fread(file.path(OUT,'00_input_audit/stromal_identity_final.csv.gz'));res<-list()
for(i in seq_len(nrow(jobs))){j<-jobs[i];u<-readRDS(file.path(OUT,'02_CellChat_highlow',j$job_id,'unfiltered.rds'));p<-u$options$parameter;for(g in c('Pericyte','Other_fibroblasts'))stopifnot(setequal(rownames(u$meta)[u$meta$group==g],identity[specimen_id==j$specimen_id&analysis_group==g,cell]));stopifnot(p$type.mean=='truncatedMean',p$trim==.1,!p$population.size,!is.na(p$raw.use),p$raw.use,p$nboot==100,p$seed.use==123);z<-st[method==j$method&specimen_id==j$specimen_id];for(s in c('high','low'))stopifnot(setequal(rownames(u$meta)[u$meta$group==paste0('C5_',s)],z[!is.na(state)&state==s,cell]));stopifnot(u$counts['C5_high']==j$high,u$counts['C5_low']==j$low,all(is.finite(u$net$prob)),all(u$net$prob>=0),all(u$net$pval>=0&u$net$pval<=1));res[[i]]<-data.table(job_id=j$job_id,parameters_match=TRUE,barcodes_states_match=TRUE,finite_arrays=TRUE,high_cells=j$high,low_cells=j$low,LR_candidates=dim(u$net$prob)[3]);}
writecsv(rbindlist(res),file.path(OUT,'00_input_audit/native_CellChat_QC.csv'));cat('NATIVE CELLCHAT QC PASS ',nrow(jobs),' jobs\n')
